import {migrateState,addTreatment,updateTreatment,nextSession,remainingSessions,treatmentStatus,treatmentMetrics,treatmentId,scheduleNextSession,appointmentId,seed,addAppointment,appointments,run,respond,reschedule,retry,metrics,labels} from './domain.js';
const $=id=>document.getElementById(id),key='laura-demo-v1';let state;try{state=JSON.parse(localStorage.getItem(key));if(!state?.appointments||!state?.messages||!state?.tasks||!state?.now)state=null;}catch{}state??=seed();migrateState(state);run(state);let editing=null,editingTreatment=null,schedulingTreatment=null;
const fmt=(date,options={dateStyle:'medium',timeStyle:'short'})=>new Intl.DateTimeFormat('es-MX',{timeZone:'America/Monterrey',...options}).format(new Date(date));
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function button(text,fn,cls){const b=el('button',text,cls);b.type='button';b.addEventListener('click',()=>act(fn));return b;}
function notify(text,error=false){$('notice').textContent=text;$('notice').className=error?'error':'';}
function act(fn){try{const result=fn();save();render();if(typeof result==='string')notify(result);}catch(e){notify(e.message,true);}}
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{notify('No se pudo guardar en este navegador. Los cambios durarán solo esta sesión.',true);}}
function render(){renderTreatments();for(const [k,v]of Object.entries(metrics(state)))$(k).textContent=v;$('clock').textContent=fmt(state.now);const list=appointments(state,{query:$('search').value,status:$('filter').value});$('visible-count').textContent=`${list.length} citas`;$('appointments').replaceChildren();for(const a of list){const row=el('article',undefined,'appointment'),tile=el('div',undefined,'date-tile');tile.append(el('span',fmt(a.start,{month:'short'})),el('strong',fmt(a.start,{day:'2-digit'})));const body=el('div',undefined,'appointment-main');body.append(el('h3',a.patient),el('p',fmt(a.start)),el('p',a.consent?'Recordatorios autorizados':'Sin autorización de recordatorios'));const bottom=el('div',undefined,'appointment-bottom');bottom.append(el('span',labels[a.status],`badge ${a.status}`),button('Reprogramar',()=>openDialog(a)));body.append(bottom);row.append(tile,body);$('appointments').append(row);}if(!list.length)$('appointments').append(el('p','No hay citas con estos filtros.','empty'));
$('tasks').replaceChildren();for(const t of state.tasks){const div=el('div',undefined,'task');div.append(el('strong','Solicitud de cambio'),el('span',t.text));$('tasks').append(div);}for(const a of state.appointments.filter(a=>a.status==='pending'&&Date.parse(a.start)>Date.parse(state.now)&&Date.parse(a.start)-Date.parse(state.now)<=24*36e5)){const div=el('div',undefined,'task');div.append(el('strong',a.patient),el('span','Próxima cita sin confirmar. Conserva su horario.'));$('tasks').append(div);}if(!$('tasks').children.length)$('tasks').append(el('p','Todo en orden. No hay acciones pendientes.','empty'));
$('messages').replaceChildren();for(const m of [...state.messages].reverse()){const a=state.appointments.find(a=>a.id===m.appointmentId),card=el('article',undefined,'message'),head=el('div',undefined,'message-head');const status={delivered:'Entregado · simulado',failed:'Fallo de envío',obsolete:'Obsoleto'};head.append(el('strong',a?.patient??'Cita'),el('span',status[m.status],`badge ${m.status}`));card.append(head,el('small',`Aviso ${m.window} h · revisión ${m.revision}`),el('p',m.text));const actions=el('div',undefined,'message-actions');if(m.status==='failed')actions.append(button('Reintentar envío',()=>{retry(state,m.id);return 'Mensaje entregado en la simulación.';}));if(m.status==='delivered'&&a.revision===m.revision&&a.status==='pending'){for(const [action,text]of [['confirmed','Confirmar'],['change_requested','Solicitar cambio'],['cancelled','Cancelar']])actions.append(button(text,()=>{respond(state,m.id,action);return action==='change_requested'?'Solicitud recibida. El horario se conserva hasta acordar otro.':'Respuesta registrada en el demo.';}));}else if(m.status==='delivered'&&a.status!=='pending')card.append(el('small',`Respuesta actual: ${labels[a.status]}`));card.append(actions);$('messages').append(card);}if(!state.messages.length)$('messages').append(el('p','Todavía no hay recordatorios. Ejecuta la automatización cuando haya citas dentro de las próximas 48 horas.','empty'));}
function localInput(iso){const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Monterrey',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(iso));return parts.replace(' ','T');}
function openDialog(a,treatment){schedulingTreatment=treatment?.id??null;editing=a?.id??null;$('dialog-title').textContent=editing?'Reprogramar cita':treatment?'Programar próxima sesión':'Nueva cita de prueba';$('patient').value=a?.patient??treatment?.patient??'';$('patient').readOnly=!!treatment;$('patient').required=!editing;$('name-label').hidden=!!editing;$('consent-label').hidden=!!editing;$('consent').checked=a?.consent??true;$('start').value=localInput(a?.start??new Date(Date.parse(state.now)+30*36e5).toISOString());$('form-error').textContent='';$('appointment-dialog').showModal();}
$('open-add').onclick=()=>openDialog();$('close-dialog').onclick=()=>$('appointment-dialog').close();$('appointment-form').onsubmit=e=>{e.preventDefault();try{const iso=new Date(`${$('start').value}:00-06:00`).toISOString();if(editing)reschedule(state,editing,iso);else if(schedulingTreatment)scheduleNextSession(state,schedulingTreatment,{id:appointmentId(state),patient:$('patient').value,start:iso,consent:$('consent').checked});else addAppointment(state,{id:appointmentId(state),patient:$('patient').value,start:iso,consent:$('consent').checked});run(state);save();render();$('appointment-dialog').close();notify(editing?'Cita reprogramada. Los avisos anteriores quedaron obsoletos.':'Cita ficticia guardada.');}catch(err){$('form-error').textContent=err.message;}};
$('run').onclick=()=>act(()=>{const count=run(state,$('fail-next').checked);$('fail-next').checked=false;return count?`${count} recordatorio(s) procesados en la simulación.`:'Sin nuevos recordatorios. No se duplicaron envíos.';});$('advance').onclick=()=>act(()=>{state.now=new Date(Date.parse(state.now)+24*36e5).toISOString();const count=run(state,$('fail-next').checked);$('fail-next').checked=false;return `Reloj avanzado 24 horas. ${count} recordatorio(s) procesados.`;});for(const id of ['search','filter'])$(id).addEventListener('input',render);$('reset').onclick=()=>act(()=>{state=seed();return 'Demo restablecido con datos ficticios.';});
function renderTreatments(){
 const counts=treatmentMetrics(state);$('treatment-metrics').replaceChildren();for(const [key,text]of [['active','En seguimiento'],['remaining','Sesiones pendientes'],['withoutNext','Sin próxima sesión'],['finished','Finalizados']]){const item=el('div');item.append(el('strong',counts[key]),el('span',text));$('treatment-metrics').append(item);}
 $('treatments').replaceChildren();for(const t of state.treatments){const card=el('article',undefined,'treatment-card');const head=el('div',undefined,'section-head');head.append(el('h3',t.patient),el('span',treatmentStatus(t),`badge ${remainingSessions(t)?'pending':'confirmed'}`));card.append(head,el('p',t.label,'treatment-label'));const counts=el('div',undefined,'session-counts');for(const [n,label]of [[t.total,'Totales'],[t.completed,'Realizadas'],[remainingSessions(t),'Pendientes']]){const col=el('div');col.append(el('strong',n),el('span',label));counts.append(col);}card.append(counts);const next=nextSession(state,t),nextBox=el('div',undefined,'next-session');nextBox.append(el('strong','Próxima sesión'),el('p',next?fmt(next.start):remainingSessions(t)?'Sin próxima sesión programada':'Tratamiento finalizado'));if(next?.status==='change_requested')nextBox.append(el('span','Solicitó cambio · horario conservado','badge'));card.append(nextBox);const actions=el('div',undefined,'treatment-actions');actions.append(button('Editar sesiones / vincular',()=>openTreatment(t)));if(remainingSessions(t)>0)actions.append(button(next?'Programar otra cita':'Programar próxima sesión',()=>openDialog(null,t)));card.append(actions);$('treatments').append(card);}if(!state.treatments.length)$('treatments').append(el('p','Aún no hay tratamientos. Registra uno con un paciente ficticio.','empty'));
}
function nextOptions(){const select=$('t-next'),old=select.value,patient=$('t-patient').value.trim().toLocaleLowerCase();select.replaceChildren(el('option','Sin próxima sesión programada'));select.firstChild.value='';for(const a of appointments(state)){if(a.patient.trim().toLocaleLowerCase()!==patient||a.status==='cancelled'||Date.parse(a.start)<=Date.parse(state.now)||state.treatments.some(t=>t.id!==editingTreatment&&remainingSessions(t)>0&&t.nextAppointmentId===a.id))continue;const option=el('option',`${fmt(a.start)} · ${labels[a.status]}`);option.value=a.id;select.append(option);}select.value=[...select.options].some(o=>o.value===old)?old:'';const finished=Number($('t-completed').value)===Number($('t-total').value)&&Number($('t-total').value)>=2;select.disabled=finished;if(finished)select.value='';$('t-link-help').textContent=finished?'Al finalizar se elimina el vínculo; la cita permanece en agenda.':'Solo citas futuras del mismo paciente, disponibles para vincular.';}
function openTreatment(t){editingTreatment=t?.id??null;$('treatment-title').textContent=t?'Editar tratamiento':'Registrar tratamiento';$('t-patient').value=t?.patient??'';$('t-label').value=t?.label??'';$('t-total').value=t?.total??2;$('t-completed').value=t?.completed??0;$('t-error').textContent='';nextOptions();$('t-next').value=nextSession(state,t??{total:2,completed:0,patient:''})?.id??'';$('treatment-dialog').showModal();}
$('open-treatment').onclick=()=>openTreatment();$('close-treatment').onclick=()=>$('treatment-dialog').close();for(const id of ['t-patient','t-total','t-completed'])$(id).addEventListener('input',nextOptions);$('treatment-form').onsubmit=e=>{e.preventDefault();try{const data={id:editingTreatment??treatmentId(state),patient:$('t-patient').value,label:$('t-label').value,total:Number($('t-total').value),completed:Number($('t-completed').value),nextAppointmentId:$('t-next').value||null};if(editingTreatment)updateTreatment(state,editingTreatment,data);else addTreatment(state,data);save();render();$('treatment-dialog').close();notify('Sesiones actualizadas manualmente. La agenda y sus mensajes se conservan.');}catch(error){$('t-error').textContent=error.message;}};
save();render();
